original=_module("original",'"""QuantiFi 2026 local research candidate: APPROXIMATE replay only.\nGenerated by tools/build_submission.py; no private data or file access.\nRename to your official Team##QuantiFi2026.py only when preparing submission.\nNo submission, login, or official backtest has been performed.\n"""\nimport json\nimport math\nfrom types import SimpleNamespace\nfrom datamodel import Order\n\nLIMITS = {\'AMETHYST\': 50, \'TOFFEE_CAKE\': 50, \'PAPER_LANTERNS\': 50, \'TELLURIUM\': 40, \'JELLY\': 50, \'PEANUT_BUTTER\': 50, \'DRAGONFRUIT\': 40, \'GRANADILLA\': 40, \'MANGOSTEEN\': 40, \'FRUIT_BASKET\': 40, \'LYCHEE\': 200, \'WHITE_PEARLS\': 20, \'BLACK_PEARLS\': 20, \'GOLDEN_PEARLS\': 20, \'PINK_PEARLS\': 20, \'BLUE_PEARLS\': 20, \'VOUCHER_6800\': 50, \'VOUCHER_7000\': 50, \'VOUCHER_7200\': 50, \'VOUCHER_7300\': 50, \'VOUCHER_7400\': 50, \'VOUCHER_7500\': 50, \'VOUCHER_7600\': 50, \'VOUCHER_7750\': 50, \'VOUCHER_7900\': 50, \'VOUCHER_8100\': 50}\n\ndef read_memory(value):\n    try:\n        obj = json.loads(value) if isinstance(value, str) and value else {}\n        return obj if isinstance(obj, dict) else {}\n    except (ValueError, TypeError):\n        return {}\n\ndef top(book):\n    try:\n        if book is None or not book.buy_orders or (not book.sell_orders):\n            return None\n        if any((type(p) is not int or p < 0 or type(q) is not int or (q <= 0) for p, q in book.buy_orders.items())):\n            return None\n        if any((type(p) is not int or p <= 0 or type(q) is not int or (q >= 0) for p, q in book.sell_orders.items())):\n            return None\n        b, a = (max(book.buy_orders), min(book.sell_orders))\n        if b >= a:\n            return None\n        return (b, a, (b + a) / 2, book.buy_orders[b], -book.sell_orders[a])\n    except (AttributeError, TypeError, ValueError, OverflowError):\n        return None\n\ndef target_orders(symbol, book, position, target, clip=5):\n    t = top(book)\n    if t is None or type(position) is not int:\n        return []\n    target = max(-LIMITS[symbol], min(LIMITS[symbol], int(target)))\n    diff = target - position\n    if diff > 0:\n        return [Order(symbol, t[1], min(diff, clip, t[4]))]\n    if diff < 0 and t[0] > 0:\n        return [Order(symbol, t[0], -min(-diff, clip, t[3]))]\n    return []\n\n"""A: bounded AMETHYST maker. Official example supplies fair value 10000.\n\nNo historical dataset, clock regimes, hidden instance state, or synthetic fills.\nResearch uses core helpers; the integration builder must inline them.\n"""\nA_DEFAULT_CONFIG = {\'fair_value\': 10000, \'min_edge\': 1, \'position_cap\': 20, \'order_size\': 5, \'quote_improvement\': 0, \'inventory_step\': 0}\n\nclass AMETHYSTMaker:\n\n    def __init__(self, config=None):\n        self.config = dict(A_DEFAULT_CONFIG)\n        if config is not None:\n            self.config.update(config)\n        for key, value in self.config.items():\n            if type(value) is not int:\n                raise ValueError(\'A configuration values must be integers\')\n        c = self.config\n        if c[\'fair_value\'] <= 1 or c[\'min_edge\'] < 1 or (not 1 <= c[\'position_cap\'] <= LIMITS[\'AMETHYST\']) or (c[\'order_size\'] < 1) or (c[\'quote_improvement\'] < 0) or (c[\'inventory_step\'] < 0):\n            raise ValueError(\'invalid A configuration\')\n\n    def run(self, state):\n        p = \'AMETHYST\'\n        book = state.order_depths.get(p)\n        t = top(book)\n        position = state.position.get(p, 0)\n        if t is None or type(position) is not int or abs(position) > LIMITS[p]:\n            return ({}, 0, \'{}\')\n        c = self.config\n        cap = c[\'position_cap\']\n        buy_qty = max(0, min(c[\'order_size\'], cap - position))\n        sell_qty = max(0, min(c[\'order_size\'], cap + position))\n        retreat = abs(position) // c[\'inventory_step\'] if c[\'inventory_step\'] else 0\n        bid_ceiling = c[\'fair_value\'] - c[\'min_edge\'] - (retreat if position > 0 else 0)\n        ask_floor = c[\'fair_value\'] + c[\'min_edge\'] + (retreat if position < 0 else 0)\n        bid = min(t[0] + c[\'quote_improvement\'], bid_ceiling, t[1] - 1)\n        ask = max(t[1] - c[\'quote_improvement\'], ask_floor, t[0] + 1)\n        orders = []\n        if buy_qty and bid > 0:\n            orders.append(Order(p, int(bid), int(buy_qty)))\n        if sell_qty and ask > 0:\n            orders.append(Order(p, int(ask), -int(sell_qty)))\n        return ({p: orders}, 0, \'{}\')\n\n"""F: causal neighboring-strike option relative value, with optional actual-fill delta hedge.\n\nBlack-Scholes-style r=q=0 total-variance formula is an explicit modeling assumption.\nNo option exercise, settlement, conversion, annualized volatility, or known fair price.\nOnly the target option and LYCHEE can receive orders; references supply current data.\n"""\nF_TARGET = \'VOUCHER_7500\'\nF_UNDERLYING = \'LYCHEE\'\nF_LOW = \'VOUCHER_7400\'\nF_HIGH = \'VOUCHER_7600\'\nF_PRODUCTS = [F_UNDERLYING, F_LOW, F_TARGET, F_HIGH]\nF_DEFAULTS = {\'edge\': 3.0, \'hedge\': False, \'hedge_band\': 2.0, \'option_cap\': 10, \'underlying_cap\': 20, \'clip\': 2, \'exit_edge\': 1.0}\n\ndef F_normal_cdf(x):\n    return 0.5 * (1.0 + math.erf(x / math.sqrt(2.0)))\n\ndef F_call_value_delta(spot, strike, total_variance):\n    """Undiscounted call approximation; d/dspot holds total variance fixed."""\n    if not all((isinstance(x, (int, float)) and math.isfinite(x) for x in (spot, strike, total_variance))) or spot <= 0 or strike <= 0 or (total_variance <= 0):\n        return None\n    vol_root = math.sqrt(total_variance)\n    d1 = (math.log(spot / strike) + total_variance / 2.0) / vol_root\n    d2 = d1 - vol_root\n    delta = F_normal_cdf(d1)\n    return (spot * delta - strike * F_normal_cdf(d2), delta)\n\ndef F_implied_total_variance(spot, strike, price):\n    if not all((isinstance(x, (int, float)) and math.isfinite(x) for x in (spot, strike, price))) or spot <= 0 or strike <= 0 or (price <= max(spot - strike, 0.0)) or (price >= spot):\n        return None\n    lo, hi = (1e-08, 1.0)\n    if F_call_value_delta(spot, strike, lo)[0] > price or F_call_value_delta(spot, strike, hi)[0] < price:\n        return None\n    for _ in range(28):\n        mid = (lo + hi) / 2.0\n        if F_call_value_delta(spot, strike, mid)[0] < price:\n            lo = mid\n        else:\n            hi = mid\n    return (lo + hi) / 2.0\n\ndef F_model_from_books(books):\n    """The target option book is deliberately NEVER read by calibration."""\n    underlying = top(books.get(F_UNDERLYING))\n    lower, higher = (top(books.get(F_LOW)), top(books.get(F_HIGH)))\n    if underlying is None or lower is None or higher is None:\n        return None\n    spot = underlying[2]\n    low_w = F_implied_total_variance(spot, 7400, lower[2])\n    high_w = F_implied_total_variance(spot, 7600, higher[2])\n    if low_w is None or high_w is None:\n        return None\n    total_variance = (low_w + high_w) / 2.0\n    fair, delta = F_call_value_delta(spot, 7500, total_variance)\n    return (fair, delta, total_variance)\n\nclass VoucherRelativeValue:\n\n    def __init__(self, config=None):\n        self.config = dict(F_DEFAULTS)\n        if config:\n            self.config.update(config)\n\n    def run(self, state):\n        c = self.config\n        memory = read_memory(getattr(state, \'traderData\', \'\'))\n        count = memory.get(\'calls\', 0)\n        if type(count) is not int or count < 0 or count > 1000000:\n            count = 0\n        new_memory = {\'version\': 1, \'calls\': count + 1}\n        books = getattr(state, \'order_depths\', {})\n        positions = getattr(state, \'position\', {})\n        if not isinstance(books, dict) or not isinstance(positions, dict):\n            return ({}, 0, json.dumps(new_memory))\n        q = positions.get(F_TARGET, 0)\n        hedge_q = positions.get(F_UNDERLYING, 0)\n        if type(q) is not int or type(hedge_q) is not int or abs(q) > LIMITS[F_TARGET] or (abs(hedge_q) > LIMITS[F_UNDERLYING]):\n            return ({}, 0, json.dumps(new_memory))\n        model = F_model_from_books(books)\n        target_top = top(books.get(F_TARGET))\n        if model is None or target_top is None:\n            return ({}, 0, json.dumps(new_memory))\n        fair, delta, total_variance = model\n        new_memory[\'last_total_variance\'] = total_variance\n        new_memory[\'last_model_delta\'] = delta\n        cap = min(LIMITS[F_TARGET] // 2, max(0, int(c[\'option_cap\'])))\n        target = q\n        if target_top[1] < fair - c[\'edge\']:\n            target = cap\n        elif target_top[0] > fair + c[\'edge\']:\n            target = -cap\n        elif q > 0 and target_top[0] >= fair - c[\'exit_edge\']:\n            target = 0\n        elif q < 0 and target_top[1] <= fair + c[\'exit_edge\']:\n            target = 0\n        target = max(-cap, min(cap, target))\n        orders = {}\n        option_orders = target_orders(F_TARGET, books[F_TARGET], q, target, clip=c[\'clip\'])\n        if option_orders:\n            orders[F_TARGET] = option_orders\n        if c[\'hedge\']:\n            hedge_cap = min(LIMITS[F_UNDERLYING] // 2, max(0, int(c[\'underlying_cap\'])))\n            desired = max(-hedge_cap, min(hedge_cap, round(-q * delta)))\n            if abs(desired - hedge_q) > c[\'hedge_band\']:\n                hedge_orders = target_orders(F_UNDERLYING, books[F_UNDERLYING], hedge_q, desired, clip=c[\'clip\'])\n                if hedge_orders:\n                    orders[F_UNDERLYING] = hedge_orders\n        return (orders, 0, json.dumps(new_memory, separators=(\',\', \':\'), allow_nan=False))\n\nMODULE_SPECS = {\'A\': {\'config\': {\'fair_value\': 10000, \'min_edge\': 1, \'position_cap\': 20, \'order_size\': 5, \'quote_improvement\': 0, \'inventory_step\': 0}, \'data_products\': [\'AMETHYST\'], \'traded_products\': [\'AMETHYST\']}, \'F\': {\'config\': {\'edge\': 6.0, \'hedge\': False, \'hedge_band\': 2.0, \'option_cap\': 10, \'underlying_cap\': 20, \'clip\': 2, \'exit_edge\': 1.0}, \'data_products\': [\'LYCHEE\', \'VOUCHER_7400\', \'VOUCHER_7500\', \'VOUCHER_7600\'], \'traded_products\': [\'VOUCHER_7500\']}}\nRISK_CAPS = {\'AMETHYST\':20, \'VOUCHER_7500\':10}\n\nclass Trader:\n    """QuantiFi candidate. Cold-start safe; all temporal state is in traderData.\n\n    A: AMETHYST passive fair-value quotes, soft cap 20, clip 5.\n    F: VOUCHER_7500 relative pricing, soft cap 10, clip 2; UNHEDGED.\n    Not officially backtested; see the project research report for assumptions.\n    active_modules is used only for local removal experiments; official use is Trader().\n    """\n    def __init__(self, active_modules=None):\n        self.active_modules = tuple((\'A\', \'F\') if active_modules is None else active_modules)\n        if len(set(self.active_modules)) != len(self.active_modules) or any(x not in (\'A\',\'F\') for x in self.active_modules):\n            raise ValueError(\'Unknown or duplicate module\')\n\n    def run(self, state):\n        books = getattr(state, \'order_depths\', None)\n        positions = getattr(state, \'position\', None)\n        memory = read_memory(getattr(state, \'traderData\', \'\'))\n        saved = memory.get(\'modules\', {})\n        if not isinstance(saved, dict): saved = {}\n        out_memory = {\'version\': 1, \'modules\': {}, \'risk_diagnostics\': []}\n        if not isinstance(books, dict) or not isinstance(positions, dict):\n            out_memory[\'risk_diagnostics\'].append(\'invalid_state_mapping\')\n            return {}, 0, json.dumps(out_memory, separators=(\',\', \':\'))\n        orders = {}\n        for name in self.active_modules:\n            spec = MODULE_SPECS[name]\n            text = saved.get(name, \'{}\')\n            if not isinstance(text, str): text = \'{}\'\n            view = SimpleNamespace(\n                traderData=text, timestamp=getattr(state, \'timestamp\', 0),\n                order_depths={p:books[p] for p in spec[\'data_products\'] if p in books},\n                position={p:positions[p] for p in spec[\'data_products\'] if p in positions},\n                listings=getattr(state, \'listings\', {}),\n                own_trades=getattr(state, \'own_trades\', {}),\n                market_trades=getattr(state, \'market_trades\', {}),\n                observations=getattr(state, \'observations\', None))\n            try:\n                strategy = AMETHYSTMaker(spec[\'config\']) if name == \'A\' else VoucherRelativeValue(spec[\'config\'])\n                returned = strategy.run(view)\n                if not isinstance(returned, tuple) or len(returned) != 3:\n                    out_memory[\'risk_diagnostics\'].append(name + \':invalid_module_return\')\n                    continue\n                proposed, conversions, next_text = returned\n                if isinstance(next_text, str) and next_text:\n                    json.loads(next_text)\n            except Exception as exc:\n                out_memory[\'risk_diagnostics\'].append(name + \':module_exception:\' + type(exc).__name__)\n                continue\n            if type(conversions) is not int or conversions != 0 or not isinstance(proposed, dict) or not isinstance(next_text, str):\n                out_memory[\'risk_diagnostics\'].append(name + \':invalid_module_return\')\n                continue\n            out_memory[\'modules\'][name] = next_text\n            for p, rows in proposed.items():\n                if p not in spec[\'traded_products\'] or not isinstance(rows, list):\n                    out_memory[\'risk_diagnostics\'].append(name + \':ownership_violation\')\n                    continue\n                orders.setdefault(p, []).extend(rows)\n        safe = {}\n        for p, rows in orders.items():\n            position = positions.get(p, 0)\n            cap = RISK_CAPS[p]\n            if type(position) is not int or abs(position) > LIMITS[p] or top(books.get(p)) is None:\n                out_memory[\'risk_diagnostics\'].append(p + \':invalid_position_or_book\')\n                continue\n            buys = max(0, cap-position)\n            sells = max(0, cap+position)\n            clean = []\n            for order in rows:\n                if (not isinstance(order, Order) or order.symbol != p or type(order.price) is not int\n                    or order.price <= 0 or type(order.quantity) is not int or order.quantity == 0):\n                    out_memory[\'risk_diagnostics\'].append(p + \':invalid_order\')\n                    continue\n                amount = min(abs(order.quantity), buys if order.quantity > 0 else sells)\n                if amount < abs(order.quantity):\n                    out_memory[\'risk_diagnostics\'].append(p + \':risk_clip\')\n                if amount:\n                    clean.append(Order(p, order.price, amount if order.quantity > 0 else -amount))\n                    if order.quantity > 0: buys -= amount\n                    else: sells -= amount\n            bp = [o.price for o in clean if o.quantity > 0]\n            ap = [o.price for o in clean if o.quantity < 0]\n            if bp and ap and max(bp) >= min(ap):\n                out_memory[\'risk_diagnostics\'].append(p + \':self_cross_rejected\')\n                continue\n            if clean: safe[p] = clean\n        return safe, 0, json.dumps(out_memory, separators=(\',\', \':\'), allow_nan=False)\n')
