_helpers=_module("helpers",'"""Small causal order helpers. Pending amount is prior submitted worst-side size."""\n\nPEARLS=(\'BLACK_PEARLS\',\'BLUE_PEARLS\',\'GOLDEN_PEARLS\',\'PINK_PEARLS\',\'WHITE_PEARLS\')\n\ndef pending(state, product):\n    v=getattr(state,\'pending_orders\',{}).get(product,(0,0))\n    if not isinstance(v,(tuple,list)) or len(v)!=2 or any(type(x) is not int or x<0 for x in v):\n        return (40,40)\n    return tuple(v)\n\ndef target_order(state, product, target, price, clip=None):\n    q=state.position.get(product,0); delta=target-q\n    if not delta: return []\n    side=1 if delta>0 else -1\n    n=max(0,abs(delta)-pending(state,product)[0 if side>0 else 1])\n    if clip is not None: n=min(n,clip)\n    return [Order(product,int(price),side*n)] if n else []\n',_COMMON)
_COMMON.update({k:getattr(_helpers,k) for k in ("PEARLS","pending","target_order")})
detector=_module("detector",'"""Causal directional-change detector. Standard library only; no trading.\n\nAn extreme is a historical observation. It becomes available as a confirmed\npivot only after the fixed reversal distance is observed. Confirmed events are\nnever revised. Unconfirmed extrema are stored separately and must not be used\nas if their future confirmation were known.\n"""\nfrom copy import deepcopy\nimport math\n\nVERSION = 1\nHISTORY_LIMIT = 12\n\n\ndef _price(value):\n    return type(value) in (int, float) and math.isfinite(value) and value > 0\n\n\ndef _index(value):\n    return type(value) is int and value >= 0\n\n\ndef _point(price, index, timestamp):\n    return {\'price\': float(price), \'index\': index, \'timestamp\': timestamp}\n\n\ndef _valid_point(point):\n    return (isinstance(point, dict) and _price(point.get(\'price\'))\n            and _index(point.get(\'index\')) and _index(point.get(\'timestamp\')))\n\n\ndef _validate(memory, threshold):\n    """Reject malformed state rather than silently inventing missing history."""\n    if not isinstance(memory, dict) or memory.get(\'version\') != VERSION:\n        raise ValueError(\'invalid detector memory version\')\n    if memory.get(\'threshold\') != threshold:\n        raise ValueError(\'threshold changed within detector history\')\n    if type(memory.get(\'direction\')) is not int or memory[\'direction\'] not in (-1,0,1):\n        raise ValueError(\'invalid detector direction\')\n    if not _valid_point(memory.get(\'last\')) or not _index(memory.get(\'sequence\')):\n        raise ValueError(\'invalid last observation or sequence\')\n    pivots=memory.get(\'pivots\')\n    if not isinstance(pivots, list) or len(pivots)>HISTORY_LIMIT:\n        raise ValueError(\'invalid pivot history\')\n    previous=None\n    for p in pivots:\n        if (not isinstance(p, dict) or type(p.get(\'id\')) is not int or p[\'id\']<=0\n            or p.get(\'kind\') not in (\'H\',\'L\') or not _price(p.get(\'price\'))\n            or not _price(p.get(\'confirmation_price\')) or p.get(\'threshold\')!=threshold\n            or not all(_index(p.get(k)) for k in (\'extreme_index\',\'extreme_timestamp\',\'confirmation_index\',\'confirmation_timestamp\'))\n            or p[\'extreme_index\']>=p[\'confirmation_index\']\n            or p[\'extreme_timestamp\']>=p[\'confirmation_timestamp\']\n            or p[\'confirmation_index\']>memory[\'last\'][\'index\']\n            or p[\'confirmation_timestamp\']>memory[\'last\'][\'timestamp\']):\n            raise ValueError(\'invalid confirmed pivot\')\n        if previous is not None and (p[\'id\']!=previous[\'id\']+1 or p[\'kind\']==previous[\'kind\']\n            or p[\'extreme_index\']<=previous[\'extreme_index\']\n            or p[\'confirmation_index\']<=previous[\'confirmation_index\']):\n            raise ValueError(\'invalid pivot ordering\')\n        signed=(p[\'confirmation_price\']-p[\'price\'])*(1 if p[\'kind\']==\'L\' else -1)\n        if signed<threshold:raise ValueError(\'pivot reversal below threshold\')\n        previous=p\n    if pivots and pivots[-1][\'id\']!=memory[\'sequence\']:\n        raise ValueError(\'pivot sequence mismatch\')\n    if memory[\'direction\']==0:\n        if pivots or memory[\'sequence\'] or memory.get(\'extreme\') is not None:\n            raise ValueError(\'uninitialized direction has confirmed history\')\n        if not _valid_point(memory.get(\'initial_low\')) or not _valid_point(memory.get(\'initial_high\')):\n            raise ValueError(\'invalid initial extrema\')\n        if not memory[\'initial_low\'][\'price\']<=memory[\'last\'][\'price\']<=memory[\'initial_high\'][\'price\']:\n            raise ValueError(\'last observation outside initial extrema\')\n        if any(memory[k][\'index\']>memory[\'last\'][\'index\'] or memory[k][\'timestamp\']>memory[\'last\'][\'timestamp\'] for k in (\'initial_low\',\'initial_high\')):\n            raise ValueError(\'initial extreme contains a future observation\')\n        if memory[\'initial_high\'][\'price\']-memory[\'initial_low\'][\'price\']>=threshold:\n            raise ValueError(\'unconfirmed initial range already crosses threshold\')\n    else:\n        if not pivots or not _valid_point(memory.get(\'extreme\')):\n            raise ValueError(\'missing confirmed anchor or running extreme\')\n        if pivots[-1][\'kind\'] != (\'L\' if memory[\'direction\']==1 else \'H\'):\n            raise ValueError(\'direction and confirmed anchor disagree\')\n        if memory[\'extreme\'][\'index\']<pivots[-1][\'confirmation_index\']:\n            raise ValueError(\'running extreme predates last confirmation\')\n        if (memory[\'extreme\'][\'index\']>memory[\'last\'][\'index\']\n            or memory[\'extreme\'][\'timestamp\']>memory[\'last\'][\'timestamp\']\n            or memory[\'extreme\'][\'timestamp\']<pivots[-1][\'confirmation_timestamp\']):\n            raise ValueError(\'invalid running extreme chronology\')\n        distance=memory[\'direction\']*(memory[\'extreme\'][\'price\']-memory[\'last\'][\'price\'])\n        if not 0<=distance<threshold:\n            raise ValueError(\'unconfirmed running extreme is inconsistent with last price\')\n\n\ndef step(mid, index, timestamp, memory, threshold):\n    """Return ``(new_memory, newly_confirmed_event_or_None)``.\n\n    ``index`` is an observation index, not elapsed time. Timestamp is preserved\n    without assuming its units. A repeated already-processed observation is\n    idempotent and emits no second event. New observations must increase both.\n    A caller can record all returned events; memory retains only the last12.\n    Input memory and prior event dictionaries are never mutated.\n    """\n    if not _price(mid):raise ValueError(\'mid must be finite and positive\')\n    if not _index(index) or not _index(timestamp):raise ValueError(\'index/timestamp must be nonnegative integers\')\n    if not _price(threshold):raise ValueError(\'threshold must be finite and positive\')\n    threshold=float(threshold);point=_point(mid,index,timestamp)\n    if memory is None or memory=={}:\n        return {\'version\':VERSION,\'threshold\':threshold,\'direction\':0,\n                \'sequence\':0,\'pivots\':[],\'last\':point,\n                \'initial_low\':dict(point),\'initial_high\':dict(point),\'extreme\':None},None\n    _validate(memory,threshold)\n    last=memory[\'last\']\n    if index==last[\'index\'] and timestamp==last[\'timestamp\'] and float(mid)==last[\'price\']:\n        return deepcopy(memory),None\n    if index<=last[\'index\'] or timestamp<=last[\'timestamp\']:\n        raise ValueError(\'conflicting duplicate or nonmonotone observation\')\n    m=deepcopy(memory);event=None;direction=m[\'direction\']\n\n    def confirm(extreme,kind,new_direction):\n        nonlocal event\n        m[\'sequence\']+=1\n        event={\'id\':m[\'sequence\'],\'kind\':kind,\'price\':extreme[\'price\'],\n               \'extreme_index\':extreme[\'index\'],\'extreme_timestamp\':extreme[\'timestamp\'],\n               \'confirmation_index\':index,\'confirmation_timestamp\':timestamp,\n               \'confirmation_price\':float(mid),\'threshold\':threshold}\n        m[\'pivots\']=(m[\'pivots\']+[deepcopy(event)])[-HISTORY_LIMIT:]\n        m[\'direction\']=new_direction;m[\'extreme\']=dict(point)\n        m[\'initial_low\']=None;m[\'initial_high\']=None\n\n    if direction==0:\n        if mid<m[\'initial_low\'][\'price\']:m[\'initial_low\']=dict(point)\n        if mid>m[\'initial_high\'][\'price\']:m[\'initial_high\']=dict(point)\n        if mid-m[\'initial_low\'][\'price\']>=threshold:\n            confirm(m[\'initial_low\'],\'L\',1)\n        elif m[\'initial_high\'][\'price\']-mid>=threshold:\n            confirm(m[\'initial_high\'],\'H\',-1)\n    elif direction==1:\n        if mid>m[\'extreme\'][\'price\']:m[\'extreme\']=dict(point)\n        elif m[\'extreme\'][\'price\']-mid>=threshold:\n            confirm(m[\'extreme\'],\'H\',-1)\n    else:\n        if mid<m[\'extreme\'][\'price\']:m[\'extreme\']=dict(point)\n        elif mid-m[\'extreme\'][\'price\']>=threshold:\n            confirm(m[\'extreme\'],\'L\',1)\n    m[\'last\']=point\n    return m,deepcopy(event)\n')
structure=_module("structure",'"""Narrow, auditable Elliott-style rules on *confirmed* causal pivots.\n\nThis module does not detect pivots, observe current quotes, place orders, choose\nparameters or backdate entries. `available_index` is the earliest possible\ndecision index, not a traded extreme. The default caller must supply only the\nconfirmed pivots available now; asof_index adds an explicit availability check.\n"""\nimport math\n\nMODES = (\'swingbreak\', \'wave3\', \'fiveabc\')\nNEEDED = {\'swingbreak\': 2, \'wave3\': 3, \'fiveabc\': 9}\nFIB_W2 = (0.382, 0.786)\nFIB_W4 = (0.236, 0.5)\nFIB_ABC = (0.382, 0.786)\n\n\ndef _number(x):\n    return type(x) in (int, float) and math.isfinite(x)\n\n\ndef _validate(pivots, asof_index=None):\n    if not isinstance(pivots, (list, tuple)):\n        return \'pivots_not_sequence\'\n    if asof_index is not None and (type(asof_index) is not int or asof_index < 0):\n        return \'invalid_asof_index\'\n    previous = None\n    for p in pivots:\n        if not isinstance(p, dict):\n            return \'pivot_not_dict\'\n        if type(p.get(\'id\')) is not int or p[\'id\'] < 1:\n            return \'invalid_pivot_id\'\n        if p.get(\'kind\') not in (\'H\', \'L\'):\n            return \'invalid_pivot_kind\'\n        if not _number(p.get(\'price\')) or p[\'price\'] <= 0:\n            return \'invalid_pivot_price\'\n        for k in (\'extreme_index\', \'extreme_timestamp\', \'confirmation_index\', \'confirmation_timestamp\'):\n            if type(p.get(k)) is not int or p[k] < 0:\n                return \'invalid_pivot_coordinate\'\n        if p[\'extreme_index\'] >= p[\'confirmation_index\']:\n            return \'confirmation_not_after_extreme\'\n        if p[\'extreme_timestamp\'] >= p[\'confirmation_timestamp\']:\n            return \'confirmation_time_not_after_extreme\'\n        if asof_index is not None and p[\'confirmation_index\'] > asof_index:\n            return \'future_confirmation\'\n        if previous is not None:\n            if p[\'id\'] <= previous[\'id\']:\n                return \'nonincreasing_pivot_id\'\n            if p[\'kind\'] == previous[\'kind\']:\n                return \'nonalternating_pivots\'\n            if (p[\'extreme_index\'] <= previous[\'extreme_index\'] or\n                p[\'confirmation_index\'] <= previous[\'confirmation_index\'] or\n                p[\'extreme_timestamp\'] <= previous[\'extreme_timestamp\'] or\n                p[\'confirmation_timestamp\'] <= previous[\'confirmation_timestamp\']):\n                return \'nonincreasing_pivot_coordinate\'\n            if (p[\'kind\'] == \'H\' and p[\'price\'] <= previous[\'price\']) or (p[\'kind\'] == \'L\' and p[\'price\'] >= previous[\'price\']):\n                return \'nonpositive_swing_length\'\n        previous = p\n    return None\n\n\ndef _side(pivots):\n    return 1 if pivots[-1][\'kind\'] == \'L\' else -1\n\n\ndef _impulse(prices):\n    """Prices transformed by desired side, so every test is bullish."""\n    if len(prices) != 6:\n        return False, \'need_six_impulse_pivots\', {}\n    a, b, c, d, e, f = prices\n    w1, w3, w5 = b-a, d-c, f-e\n    ratios = {\'wave1_length\': w1, \'wave3_length\': w3, \'wave5_length\': w5,\n              \'wave2_retracement\': (b-c)/w1,\n              \'wave4_retracement\': (d-e)/w3}\n    for ok, reason in ((c > a, \'wave2_beyond_or_equal_start\'),\n                       (d > b, \'wave3_does_not_extend_wave1\'),\n                       (e > b, \'wave4_overlaps_wave1\'),\n                       (f > d, \'wave5_does_not_extend_wave3\'),\n                       (w3 >= min(w1, w5), \'wave3_is_shortest\')):\n        if not ok:\n            return False, reason, ratios\n    return True, \'impulse_valid\', ratios\n\n\ndef impulse(pivots, asof_index=None):\n    """Latest six pivots: completed five-wave count, separate from ABC."""\n    if not isinstance(pivots, (list, tuple)) or len(pivots) < 6:\n        return {\'valid\': False, \'reason\': \'insufficient_impulse_pivots\', \'ratios\': {}}\n    tail = pivots[-6:]\n    error = _validate(tail, asof_index)\n    if error:\n        return {\'valid\': False, \'reason\': error, \'ratios\': {}}\n    # A long impulse ends at H; a short one ends at L.\n    side = 1 if tail[0][\'kind\'] == \'L\' else -1\n    ok, reason, ratios = _impulse([side*p[\'price\'] for p in tail])\n    return {\'valid\': ok, \'reason\': reason, \'side\': side, \'ratios\': ratios,\n            \'pivot_ids\': [p[\'id\'] for p in tail],\n            \'available_index\': tail[-1][\'confirmation_index\'],\n            \'available_timestamp\': tail[-1][\'confirmation_timestamp\']}\n\n\ndef _pack(tail, mode, fib, side, breakout, stop, ratios, labels):\n    legs = []\n    for i, (start, end) in enumerate(zip(tail, tail[1:])):\n        legs.append({\'label\': labels[i+1], \'start_pivot_id\': start[\'id\'],\n                     \'end_pivot_id\': end[\'id\'],\n                     \'start_extreme_index\': start[\'extreme_index\'],\n                     \'end_extreme_index\': end[\'extreme_index\'],\n                     \'start_price\': start[\'price\'], \'end_price\': end[\'price\'],\n                     \'absolute_length\': abs(end[\'price\']-start[\'price\']),\n                     \'available_index\': end[\'confirmation_index\']})\n    ident = mode+(\':fib\' if fib else \':plain\')+\':\'+str(side)+\':\'+\'-\'.join(\n        str(p[\'id\'])+\'@\'+str(p[\'confirmation_index\']) for p in tail)\n    return {\'setup_id\': ident, \'mode\': mode, \'fib\': fib, \'side\': side,\n            \'breakout\': breakout, \'stop\': stop,\n            \'available_index\': tail[-1][\'confirmation_index\'],\n            \'available_timestamp\': tail[-1][\'confirmation_timestamp\'],\n            \'pivot_ids\': [p[\'id\'] for p in tail],\n            \'wave_ids\': dict(zip(labels, [p[\'id\'] for p in tail])),\n            \'legs\': legs, \'ratios\': ratios}\n\n\ndef inspect(pivots, mode, fib=False, asof_index=None):\n    """Return eligibility and rejection reason without observing future prices.\n\n    `impulse_valid` and `abc_valid` are separately countable diagnostics for\n    full-five-plus-ABC candidates. No valid setup implies any guaranteed fill.\n    """\n    if mode not in MODES:\n        raise ValueError(\'unknown structure mode\')\n    if type(fib) is not bool:\n        raise ValueError(\'fib must be bool\')\n    if mode == \'swingbreak\' and fib:\n        raise ValueError(\'two-pivot swingbreak has no impulse Fibonacci denominator\')\n    result = {\'valid\': False, \'reason\': \'insufficient_pivots\', \'setup\': None,\n              \'impulse_valid\': False, \'abc_valid\': False, \'ratios\': {}}\n    if not isinstance(pivots, (list, tuple)) or len(pivots) < NEEDED[mode]:\n        return result\n    tail = pivots[-NEEDED[mode]:]\n    error = _validate(tail, asof_index)\n    if error:\n        result[\'reason\'] = error\n        return result\n    side = _side(tail)\n    prices = [side*p[\'price\'] for p in tail]\n    ratios = {}\n    if mode == \'swingbreak\':\n        breakout = tail[0][\'price\']; labels = (\'prior_extreme\', \'pullback\')\n    elif mode == \'wave3\':\n        a, b, c = prices\n        ratios = {\'wave1_length\': b-a, \'wave2_retracement\': (b-c)/(b-a)}\n        result[\'ratios\'] = ratios\n        if not c > a:\n            result[\'reason\'] = \'wave2_beyond_or_equal_start\'\n            return result\n        if fib and not FIB_W2[0] <= ratios[\'wave2_retracement\'] <= FIB_W2[1]:\n            result[\'reason\'] = \'fib_wave2_outside_band\'\n            return result\n        breakout = tail[1][\'price\']; labels = (\'W0\', \'W1\', \'W2\')\n    else:\n        ok, reason, ratios = _impulse(prices[:6])\n        result[\'ratios\'] = ratios\n        result[\'impulse_valid\'] = ok\n        if not ok:\n            result[\'reason\'] = reason\n            return result\n        if not prices[7] < prices[5]:\n            result[\'reason\'] = \'B_not_below_wave5\'\n            return result\n        if not prices[8] < prices[6]:\n            result[\'reason\'] = \'C_not_beyond_A\'\n            return result\n        result[\'abc_valid\'] = True\n        ratios[\'abc_retracement\'] = (prices[5]-prices[8])/(prices[5]-prices[0])\n        for name, bounds in ((\'wave2_retracement\', FIB_W2),\n                             (\'wave4_retracement\', FIB_W4),\n                             (\'abc_retracement\', FIB_ABC)):\n            if fib and not bounds[0] <= ratios[name] <= bounds[1]:\n                result[\'reason\'] = \'fib_\'+name+\'_outside_band\'\n                return result\n        breakout = tail[7][\'price\']; labels = (\'W0\', \'W1\', \'W2\', \'W3\', \'W4\', \'W5\', \'A\', \'B\', \'C\')\n    result[\'valid\'] = True\n    result[\'reason\'] = \'eligible\'\n    result[\'ratios\'] = ratios\n    result[\'setup\'] = _pack(tail, mode, fib, side, breakout, tail[-1][\'price\'], ratios, labels)\n    return result\n\n\ndef setup(pivots, mode, fib=False, asof_index=None):\n    """Return a current eligible setup or None; never emits an order."""\n    return inspect(pivots, mode, fib, asof_index)[\'setup\']\n')
