_wave=_module("wave_transfer",'"""Causal wave entries, confirmed-pivot stops, full-cap execution with pending."""\nfrom copy import deepcopy\n\ndef fresh():return {\'v\':1,\'n\':-1,\'last_ts\':None,\'detector\':{},\'ema\':{},\'event\':None,\'consumed\':None,\'diagnostic\':{}}\n\ndef propose(state,memory,c):\n    m=deepcopy(memory) if memory else fresh();p=c[\'product\'];book=state.order_depths.get(p);t=top(book)\n    if t is None:return {},m\n    q=state.position.get(p,0);ts=state.timestamp\n    if (not isinstance(m,dict) or m.get(\'v\')!=1 or type(m.get(\'n\'))is not int or\n        not isinstance(m.get(\'ema\'),dict) or not isinstance(m.get(\'detector\'),dict)):\n        m=fresh();m[\'last_ts\']=ts;m[\'diagnostic\']={\'reason\':\'malformed_one_generation_pause\'};return {},m\n    if m[\'last_ts\'] is not None and ts<=m[\'last_ts\']:\n        m[\'diagnostic\']={\'reason\':\'nonadvancing_callback_no_new_order\'};return {},m\n    m[\'n\']+=1;n=m[\'n\'];m[\'last_ts\']=ts;mid=t[2];cap=c[\'cap\'];pv=None;setup=None;side=0\n    d={\'index\':n,\'timestamp\':ts,\'mid\':mid,\'pivot\':None,\'setup\':None,\'signal\':0,\'action\':\'none\',\'reason\':\'\'};m[\'diagnostic\']=d\n    if c[\'signal\']==\'wave\':\n        try:m[\'detector\'],pv=detector.step(mid,n,ts,m[\'detector\'],c[\'threshold\'])\n        except ValueError:\n            # Explicit pause, no invented pivot history; held inventory recovers below.\n            m[\'detector\']={};d[\'reason\']=\'invalid_detector_pause\';return {},m\n        d[\'pivot\']=pv\n        setup=structure.setup(m[\'detector\'][\'pivots\'],c[\'mode\'],c[\'fib\'],asof_index=n)\n        d[\'setup\']=setup\n        if setup is not None and setup[\'side\']*(mid-setup[\'breakout\'])>0:side=setup[\'side\']\n    else:\n        em=m[\'ema\'];count=em.get(\'n\',0);fast=em.get(\'fast\',mid);slow=em.get(\'slow\',mid)\n        if count:\n            fast+=2/(c[\'fast\']+1)*(mid-fast);slow+=2/(c[\'slow\']+1)*(mid-slow)\n        direction=1 if fast>slow else -1 if fast<slow else em.get(\'side\',0)\n        m[\'ema\']={\'n\':count+1,\'fast\':round(fast,6) if c.get(\'round6\') else fast,\'slow\':round(slow,6) if c.get(\'round6\') else slow,\'side\':direction}\n        if count+1>=c[\'warmup\']:side=direction\n    d[\'signal\']=side\n    e=m[\'event\'];held=pending(state,p)\n    if e is None and q:\n        e={\'side\':1 if q>0 else -1,\'phase\':\'exit\',\'stop\':None,\'seen_fill\':True,\'id\':\'recover\',\'start_index\':n};m[\'event\']=e;d[\'reason\']=\'orphan_position_exit\'\n    def send(target,action,reason):\n        diff=target-q\n        if not diff:return {}\n        qty=t[4] if diff>0 else t[3];price=t[1] if diff>0 else t[0]\n        orders=target_order(state,p,target,price,clip=qty)\n        if orders:d.update(action=action,reason=reason,target=target)\n        return {p:orders} if orders else {}\n    if e is not None:\n        if q:e[\'seen_fill\']=True\n        if q and q*e[\'side\']<0:e[\'phase\']=\'exit\';d[\'reason\']=\'unexpected_side_exit\'\n        if c[\'signal\']==\'wave\' and pv is not None and e[\'phase\']!=\'exit\':\n            if pv[\'kind\']==(\'L\' if e[\'side\']>0 else \'H\'):\n                if e[\'stop\'] is None or e[\'side\']*(pv[\'price\']-e[\'stop\'])>0:e[\'stop\']=pv[\'price\']\n        stop_hit=e[\'stop\'] is not None and e[\'side\']*(mid-e[\'stop\'])<=0\n        if e[\'phase\']!=\'exit\' and (stop_hit or side*e[\'side\']<0):\n            e[\'phase\']=\'exit\';d[\'reason\']=\'confirmed_stop\' if stop_hit else \'opposite_signal\'\n        if e[\'phase\']==\'exit\':\n            if q:return send(0,\'exit\',d[\'reason\'] or \'latched_exit\'),m\n            if any(held):d[\'reason\']=\'wait_pending_exit\';return {},m\n            m[\'event\']=None;d[\'action\']=\'exit_complete\';return {},m\n        return send(e[\'side\']*cap,\'stage\',\'retain_original_target\'),m\n    if any(held):d[\'reason\']=\'wait_prior_generation\';return {},m\n    if not side:return {},m\n    ident=setup[\'setup_id\'] if setup is not None else \'ema:\'+str(side)\n    if c[\'signal\']==\'wave\' and ident==m[\'consumed\']:d[\'reason\']=\'setup_already_consumed\';return {},m\n    m[\'consumed\']=ident;m[\'event\']={\'side\':side,\'phase\':\'holding\',\'stop\':setup[\'stop\'] if setup else None,\'seen_fill\':False,\'id\':ident,\'start_index\':n}\n    return send(side*cap,\'entry\',\'confirmed_breakout\' if setup else \'ema_direction\'),m\n',_COMMON)
