_portfolio=_module("portfolio",'"""Single shared risk gate and memory namespace for all components.\n\nOne generation of prior submitted orders is conservatively reserved, regardless\nof actual fills. This is an explicit supported lifetime assumption, not a claim\nof safety for indefinitely persistent orders. Same-product requests share caps;\ncrossing opposite proposals are canceled before sending anything to the engine.\n"""\nimport importlib\nimport json\nfrom types import SimpleNamespace, MappingProxyType\n\ndef load_plugin(name):\n    if name==\'af\': return af\n    if name in (\'pink\',\'basket\',\'passive\'): return importlib.import_module(\'research.pearls_execution_20261028.studies.\'+name+\'.strategy\')\n    return importlib.import_module(\'research.strategy_complementarity_20261028.studies.\'+name+\'.strategy\')\n\nclass Trader:\n    def __init__(self,config):\n        self.config=config\n    def run(self,state):\n        malformed=False\n        try:\n            saved=json.loads(state.traderData) if state.traderData else {}\n            malformed=not isinstance(saved,dict)\n        except (TypeError,ValueError): saved={}; malformed=True\n        if not malformed and state.traderData and not isinstance(saved.get(\'pending\'),dict): malformed=True\n        if not state.traderData and (any(state.position.values()) or state.timestamp!=0): malformed=True\n        if malformed:\n            # One observation without a new generation lets the supported prior\n            # generation activate/expire. No unknown pending amount is assumed 0.\n            return {},0,json.dumps({\'version\':1,\'modules\':{},\'pending\':{},\'diagnostics\':[\'malformed_memory_one_generation_pause\']})\n        previous=saved.get(\'pending\',{})\n        new={\'version\':1,\'modules\':{},\'pending\':{},\'diagnostics\':[]}; proposed={}; caps={}; owners={}\n        for item in self.config[\'components\']:\n            for p in item[\'risk_caps\']: owners.setdefault(p,item[\'id\'])\n        for item in self.config[\'components\']:\n            module=load_plugin(item[\'plugin\']); key=item[\'id\']\n            for p,cap in item[\'risk_caps\'].items():\n                caps[p]=min(LIMITS[p],caps.get(p,0)+cap)\n            memory=saved.get(\'modules\',{}).get(key,{}) if isinstance(saved.get(\'modules\',{}),dict) else {}\n            if not isinstance(memory,dict): memory={}\n            view=SimpleNamespace(**vars(state))\n            view.pending_orders=MappingProxyType({p:tuple(v) if isinstance(v,list) else v for p,v in previous.items()})\n            raw,next_memory=module.propose(view,memory,item[\'params\'])\n            new[\'modules\'][key]=next_memory\n            for p,rows in raw.items():\n                if owners[p]!=key:\n                    new[\'diagnostics\'].append(p+\':nonowner_proposals_suppressed\');continue\n                proposed.setdefault(p,[]).extend(rows)\n        safe={}\n        for p,rows in proposed.items():\n            q=state.position.get(p,0); held=previous.get(p,[0,0])\n            if not isinstance(held,list) or len(held)!=2 or any(type(x)is not int or not 0<=x<=2*LIMITS[p] for x in held):\n                # Unknown prior pending exposure: one generation of no-new-orders.\n                new[\'diagnostics\'].append(p+\':bad_pending_fail_closed\'); continue\n            if type(q)is not int or abs(q)>LIMITS[p] or top(state.order_depths.get(p)) is None: continue\n            buys=max(0,caps[p]-q-held[0]); sells=max(0,caps[p]+q-held[1]); clean=[]\n            for o in rows:\n                if not isinstance(o,Order) or o.symbol!=p or type(o.price)is not int or o.price<=0 or type(o.quantity)is not int or o.quantity==0:\n                    raise ValueError(\'invalid plugin proposal\')\n                n=min(abs(o.quantity),buys if o.quantity>0 else sells)\n                if n:\n                    clean.append(Order(p,o.price,n if o.quantity>0 else -n))\n                    if o.quantity>0: buys-=n\n                    else: sells-=n\n            bids=[o.price for o in clean if o.quantity>0]; asks=[o.price for o in clean if o.quantity<0]\n            if bids and asks and max(bids)>=min(asks):\n                clean=[]; new[\'diagnostics\'].append(p+\':conflicting_proposals_cancelled\')\n            if clean: safe[p]=clean\n        new[\'pending\']={p:[sum(o.quantity for o in rows if o.quantity>0),sum(-o.quantity for o in rows if o.quantity<0)] for p,rows in safe.items()}\n        return safe,0,json.dumps(new,separators=(\',\',\':\'),allow_nan=False)\n',dict(_COMMON,af=_PLUGINS.get("af")))
