_TJ=_module("tj",'"""Direction N: TOFFEE_CAKE / JELLY mean reversion without a hard-coded mean.\n\nOne leg per product (config[\'legs\'][symbol]). Each leg keeps a causal anchor:\n  anchor \'fixed\'  constant `fair` (control: Codex T40/J80, fair 5000 / 2000)\n         \'open\'   first mid seen today\n         \'ema\'    EMA(mid) with half-life `anchor_hl`, initialised at the first mid\n         \'mean\'   running mean of all mids seen today\nThe anchor used at tick t is the value BEFORE mid_t is folded in.\n\nEntry threshold:\n  entry_mode \'abs\'  |mid - anchor| >= entry (price points)\n             \'z\'    |mid - anchor| >= entry * s, s = sqrt(EWMA of dev^2), half-life sd_hl,\n                    available after `warmup` ticks\nRegime (Codex \'original\' rule): enter +/-cap at the threshold, hold until mid\nreturns to the anchor, then flatten; no re-entry on the tick the book goes flat.\nSafeguards (both optional):\n  max_hold  ticks in one regime before a forced exit (time stop)\n  stop_mult forced exit once |dev| >= stop_mult * threshold (adverse stop)\nAfter a forced exit, that side is blocked until mid crosses back over the anchor.\nExecution as the control: limit at the farthest visible opposing level, size = delta.\n\nOnly datamodel + standard library.\n"""\nimport json\nimport math\n\nfrom datamodel import Order\n\nLIMITS = {\'TOFFEE_CAKE\': 50, \'JELLY\': 50}\nLEG_DEFAULTS = {\'anchor\': \'ema\', \'fair\': None, \'anchor_hl\': 3000.0, \'entry_mode\': \'abs\',\n                \'entry\': 40.0, \'sd_hl\': 1000.0, \'warmup\': 300, \'cap\': 50,\n                \'max_hold\': None, \'stop_mult\': None}\nDEFAULTS = {\'legs\': {}}\n\n\ndef _num(x):\n    if isinstance(x, bool) or not isinstance(x, (int, float)):\n        return None\n    x = float(x)\n    return x if math.isfinite(x) else None\n\n\ndef _int(x, allowed=None, default=0):\n    if type(x) is not int or (allowed is not None and x not in allowed):\n        return default\n    return x\n\n\ndef _load(raw):\n    try:\n        obj = json.loads(raw) if isinstance(raw, str) and raw else {}\n    except (ValueError, TypeError):\n        return {}\n    return obj if isinstance(obj, dict) else {}\n\n\ndef _book(depth):\n    try:\n        if depth is None or not depth.buy_orders or not depth.sell_orders:\n            return None\n        bb, ba = max(depth.buy_orders), min(depth.sell_orders)\n        if type(bb) is not int or type(ba) is not int or bb >= ba:\n            return None\n        return bb, ba\n    except (AttributeError, TypeError, ValueError):\n        return None\n\n\nclass Trader:\n    def __init__(self, config=None):\n        cfg = dict(DEFAULTS)\n        cfg.update(config or {})\n        # legs: {name: leg}; a leg trades leg[\'product\'] (default: its name). Several legs\n        # on one product add their targets (a blend of anchor models), one order per product.\n        self.legs = {}\n        for name, leg in (cfg.get(\'legs\') or {}).items():\n            if name == \'_s\':\n                continue\n            leg = {**LEG_DEFAULTS, **leg}\n            leg.setdefault(\'product\', name)\n            if leg[\'product\'] in LIMITS:\n                self.legs[name] = leg\n\n    def run(self, state):\n        mem = _load(state.traderData)\n        out_mem, targets = {}, {}\n        for name, leg in self.legs.items():\n            sym = leg[\'product\']\n            m = mem.get(name) if isinstance(mem.get(name), dict) else {}\n            tob = _book(state.order_depths.get(sym))\n            if tob is None:\n                out_mem[name] = m\n                continue\n            lp = m.get(\'p\') if type(m.get(\'p\')) is int else 0     # this leg\'s notional position\n            t, m = self._leg(sym, leg, tob, lp, m)\n            m[\'p\'] = t\n            out_mem[name] = m\n            targets[sym] = targets.get(sym, 0) + t\n        # Pending reservation (same convention as the Codex portfolio gate): the size\n        # submitted last tick on the same side is assumed still working for one more\n        # tick, so a delayed fill cannot make us order the same delta twice.\n        sent = mem.get(\'_s\') if isinstance(mem.get(\'_s\'), dict) else {}\n        new_sent, orders = {}, {}\n        for sym, tgt in targets.items():\n            depth = state.order_depths.get(sym)\n            pos = state.position.get(sym, 0)\n            pos = pos if type(pos) is int else 0\n            lim = LIMITS[sym]\n            last = sent.get(sym) if type(sent.get(sym)) is int else 0\n            delta = max(-lim, min(lim, tgt)) - pos\n            if delta > 0:\n                q = min(delta - max(last, 0), lim - pos)\n                if q > 0:\n                    orders[sym] = [Order(sym, int(max(depth.sell_orders)), int(q))]\n                    new_sent[sym] = int(q)\n            elif delta < 0:\n                q = min(-delta - max(-last, 0), lim + pos)\n                if q > 0:\n                    orders[sym] = [Order(sym, int(min(depth.buy_orders)), -int(q))]\n                    new_sent[sym] = -int(q)\n        out_mem[\'_s\'] = new_sent\n        return orders, 0, json.dumps(out_mem, separators=(\',\', \':\'))\n\n    @staticmethod\n    def _leg(sym, leg, tob, pos, m):\n        """Advance one leg; returns (target position of this leg, memory).\n\n        `pos` is the leg\'s own notional position (its last target), so the exit\n        logic works per leg when several legs share one product."""\n        bb, ba = tob\n        mid = (bb + ba) / 2.0\n        n = _int(m.get(\'n\'))\n        # ---- anchor (prior value) and its update\n        a = _num(m.get(\'a\'))\n        kind = leg[\'anchor\']\n        if kind == \'fixed\':\n            anchor = float(leg[\'fair\'])\n            a_new = anchor\n        else:\n            if a is None:\n                a = mid\n            anchor = a\n            if kind == \'open\':\n                a_new = a\n            elif kind == \'ema\':\n                a_new = a + (1 - 0.5 ** (1 / float(leg[\'anchor_hl\']))) * (mid - a)\n            else:                                   # running mean\n                a_new = a + (mid - a) / (n + 1)\n        dev = mid - anchor\n        v = _num(m.get(\'v\'))\n        if leg[\'entry_mode\'] == \'z\':\n            thr = float(leg[\'entry\']) * math.sqrt(v) if (v is not None and v > 0 and n >= int(leg[\'warmup\'])) else None\n        else:\n            thr = float(leg[\'entry\'])\n        v = dev * dev if v is None else v + (1 - 0.5 ** (1 / float(leg[\'sd_hl\']))) * (dev * dev - v)\n        # ---- regime state\n        reg = _int(m.get(\'r\'), (-1, 0, 1))\n        ex = m.get(\'x\') is True\n        blk = _int(m.get(\'b\'), (-1, 0, 1))\n        h = _int(m.get(\'h\'))\n        if reg == 0 and pos:\n            reg, ex = (1 if pos > 0 else -1), True      # unknown inventory: unwind it\n        if blk and ((blk > 0 and dev >= 0) or (blk < 0 and dev <= 0)):\n            blk = 0                                     # crossed back over the anchor\n        flat_now = False\n        if ex and pos == 0:\n            reg, ex, flat_now, h = 0, False, True, 0\n        if reg and not ex:\n            h += 1\n            if (reg > 0 and dev >= 0) or (reg < 0 and dev <= 0):\n                ex = True\n            elif leg[\'max_hold\'] is not None and h > int(leg[\'max_hold\']):\n                ex, blk = True, reg\n            elif thr is not None and leg[\'stop_mult\'] is not None and abs(dev) >= float(leg[\'stop_mult\']) * thr:\n                ex, blk = True, reg\n        if reg == 0 and not flat_now and thr is not None:\n            if dev <= -thr and blk != 1:\n                reg, h = 1, 0\n            elif dev >= thr and blk != -1:\n                reg, h = -1, 0\n        new_m = {\'a\': round(a_new, 4), \'v\': round(v, 4), \'n\': min(n + 1, 10 ** 9),\n                 \'r\': reg, \'x\': ex, \'b\': blk, \'h\': h}\n        cap = max(0, min(int(leg[\'cap\']), LIMITS[sym]))\n        return (0 if ex else reg * cap), new_m\n')
TJ_CONFIG={'legs': {'T_fixed': {'product': 'TOFFEE_CAKE', 'anchor': 'fixed', 'fair': 5000, 'entry': 40, 'cap': 25}, 'T_ema': {'product': 'TOFFEE_CAKE', 'anchor': 'ema', 'anchor_hl': 3000, 'entry_mode': 'z', 'entry': 2.0, 'cap': 25}, 'J_fixed': {'product': 'JELLY', 'anchor': 'fixed', 'fair': 2000, 'entry': 80, 'cap': 25}, 'J_ema': {'product': 'JELLY', 'anchor': 'ema', 'anchor_hl': 3000, 'entry_mode': 'z', 'entry': 2.0, 'cap': 25}}}


from datamodel import Order

class Trader:
    def run(self, state):
        try:
            mem = json.loads(state.traderData) if state.traderData else {}
        except (ValueError, TypeError):
            mem = {}
        if not isinstance(mem, dict):
            mem = {}
        c_in = mem.get('c') if isinstance(mem.get('c'), str) else ''
        n_in = mem.get('n') if isinstance(mem.get('n'), str) else ''
        orders = {}
        c_out, n_out = c_in, n_in
        state.traderData = c_in
        try:
            o1, _, c_out = _CodexTrader().run(state)
            orders.update({p: v for p, v in o1.items() if p not in ('TOFFEE_CAKE', 'JELLY')})
        except Exception:
            c_out = c_in
        state.traderData = n_in
        try:
            o2, _, n_out = _TJ.Trader(TJ_CONFIG).run(state)
            orders.update({p: v for p, v in o2.items() if p in ('TOFFEE_CAKE', 'JELLY')})
        except Exception:
            n_out = n_in
        k_out = _kill_switch(state, mem.get('k'), orders)
        return orders, 0, json.dumps({'c': c_out, 'n': n_out, 'k': k_out}, separators=(',', ':'))


KILL_DD = {'TELLURIUM': 20275.5, 'FRUIT_BASKET': 40680, 'PAPER_LANTERNS': 765}


def _kill_switch(state, kmem, orders):
    """Per-product intraday kill switch for the trend modules.

    Tracks each guarded product's own PnL today (cash from own fills + position x mid).
    Once it falls more than KILL_DD[p] below its intraday peak, the product is flattened
    by crossing the touch and receives no further orders for the rest of the day.
    Thresholds = 1.5 x the largest intraday drawdown of that product on days -2/-1.
    """
    k = kmem if isinstance(kmem, dict) else {}
    ts = getattr(state, 'timestamp', 0)
    last = k.get('t') if type(k.get('t')) is int else -1
    new = {'t': ts}
    for p, lim_dd in KILL_DD.items():
        e = k.get(p) if isinstance(k.get(p), list) and len(k.get(p)) == 3 else [0.0, 0.0, 0]
        cash, peak, dead = float(e[0]), float(e[1]), int(e[2])
        if ts > last:
            for t in (getattr(state, 'own_trades', {}) or {}).get(p, []) or []:
                try:
                    q = int(t.quantity)
                    if t.buyer == 'SUBMISSION':
                        cash -= t.price * q
                    elif t.seller == 'SUBMISSION':
                        cash += t.price * q
                except (AttributeError, TypeError, ValueError):
                    continue
        pos = state.position.get(p, 0) if isinstance(state.position.get(p, 0), int) else 0
        book = state.order_depths.get(p)
        try:
            bb, ba = max(book.buy_orders), min(book.sell_orders)
        except (AttributeError, TypeError, ValueError):
            bb = ba = None
        if bb is not None and ba is not None:
            pnl = cash + pos * (bb + ba) / 2.0
            peak = max(peak, pnl)
            if not dead and peak - pnl > lim_dd:
                dead = 1
        if dead:
            orders.pop(p, None)
            if pos and bb is not None:
                if pos > 0:
                    orders[p] = [Order(p, int(bb), -min(pos, int(book.buy_orders[bb])))]
                else:
                    orders[p] = [Order(p, int(ba), min(-pos, -int(book.sell_orders[ba])))]
        new[p] = [round(cash, 2), round(peak, 2), dead]
    return new
